INSERT INTO `v1_5693ebd193831154c3cffc23c56fbab7770f4dee1962d83583975cf9d49f5810` VALUES (106601, 13161, "やってやるですよ！", "50％でアルファルピ×2000\nさらに次のイベントへ", 0, 13161, "61_inori_guts", 0);
INSERT INTO `v1_5693ebd193831154c3cffc23c56fbab7770f4dee1962d83583975cf9d49f5810` VALUES (105601, 23141, "もう一回挑戦だ！", "25％で★2迷宮遺物×1\nさらに次のイベントへ", 0, 23141, "52_ruka_fishing", 0);
INSERT INTO `v1_5693ebd193831154c3cffc23c56fbab7770f4dee1962d83583975cf9d49f5810` VALUES (105801, 23151, "まだまだ\n食べ足りません☆", "50％で次のイベントへ", 0, 23151, "92_peko_guts", 1);
INSERT INTO `v1_5693ebd193831154c3cffc23c56fbab7770f4dee1962d83583975cf9d49f5810` VALUES (106001, 23152, "それくらいで\nいいんじゃない？", "ランダムなロールの\nランダムサイン×2", 0, 23152, "92_kyaru_sad", 0);
INSERT INTO `v1_5693ebd193831154c3cffc23c56fbab7770f4dee1962d83583975cf9d49f5810` VALUES (106601, 23161, "今日はツイてるです！", "50％でアルファルピ×4000\nさらに次のイベントへ", 2000, 23161, "62_inori_guts", 1);
INSERT INTO `v1_5693ebd193831154c3cffc23c56fbab7770f4dee1962d83583975cf9d49f5810` VALUES (105501, 23162, "もうこの辺で……", "挑戦終了", 0, 23162, "62_ayumi_sad", 0);
INSERT INTO `v1_5693ebd193831154c3cffc23c56fbab7770f4dee1962d83583975cf9d49f5810` VALUES (105601, 33141, "最後にもうひと勝負！", "10％で★3迷宮遺物×1", 0, 33141, "53_ruka_fishing", 0);
INSERT INTO `v1_5693ebd193831154c3cffc23c56fbab7770f4dee1962d83583975cf9d49f5810` VALUES (105801, 33151, "えへへ～\nもうちょっとだけ……", "50％でオールセレクトサイン×２", 0, 33151, "93_peko_guts", 1);
INSERT INTO `v1_5693ebd193831154c3cffc23c56fbab7770f4dee1962d83583975cf9d49f5810` VALUES (106001, 33152, "そんなに\n食べきれないでしょ！", "ランダムなロールの\nセレクトサイン×2", 0, 33152, "93_kyaru_anger", 0);
INSERT INTO `v1_5693ebd193831154c3cffc23c56fbab7770f4dee1962d83583975cf9d49f5810` VALUES (106601, 33161, "今日のあたしは\n負け知らずです！", "50％でアルファルピ×8000", 4000, 33161, "63_inori_guts", 1);
INSERT INTO `v1_5693ebd193831154c3cffc23c56fbab7770f4dee1962d83583975cf9d49f5810` VALUES (105501, 33162, "そろそろやめた方が……", "挑戦終了", 0, 33162, "63_ayumi_worry", 0);
